args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1);root<-args[1];od<-file.path(root,"03_sldsc_scavenge/sldsc_salo")
suppressPackageStartupMessages(library(data.table));stopifnot(file.exists(file.path(od,"h2.done")),file.exists(file.path(od,"cts.done")))
h<-fread(file.path(od,"SALO_Adult_joint.results"));c<-fread(file.path(od,"SALO_Adult_CTS.cell_type_results.txt"));labels<-c("AST","ExNeu","IN","MG","OL","OPC","VASC")
stopifnot(nrow(h)==104,nrow(c)==7);hc<-h[1:7];stopifnot(all(startsWith(hc$Category,paste0(labels,"L2"))))
stopifnot(all(c$Name%in%labels));c[,cell_type:=Name];hc[,cell_type:=labels]
c[,FDR_CTS_7:=p.adjust(Coefficient_P_value,"BH")];hc[,FDR_h2_7:=p.adjust(Enrichment_p,"BH")]
global<-p.adjust(c(c$Coefficient_P_value,hc$Enrichment_p),"BH");c[,FDR_global_14:=global[1:7]];hc[,FDR_global_14:=global[8:14]]
meta<-fread(file.path(root,"03_sldsc_scavenge/annotations/SLDSC_ANNOTATION_MANIFEST.tsv"));meta<-meta[cell_type%in%labels,.(cell_type,n_eligible_cells=n_cells,n_autosomal_peaks_hg38=n_peaks_autosomal_hg38,n_peaks_hg19,mapping_rate)]
lqc<-fread(file.path(root,"03_sldsc_scavenge/ldscores/LD_SCORE_CHROMOSOME_QC.tsv"));lf<-lqc[,.(reference_all_SNP_fraction=sum(n_annotated_snps)/sum(n_reference_snps),n_common_annotated_snps=sum(n_common_annotated_snps)),by=cell_type];meta<-merge(meta,lf,by="cell_type")
c<-merge(c,meta,by="cell_type");hc<-merge(hc,meta,by="cell_type")
c[,association_direction:=ifelse(Coefficient>0,"POSITIVE_CONDITIONAL_TAU","NONPOSITIVE_CONDITIONAL_TAU")];hc[,enrichment_direction:=ifelse(Enrichment>1,"ENRICHMENT","DEPLETION_OR_NULL")]
c[,`:=`(dataset="PMID37824647 author Adult",n_donors=2,scope="STRICT_CLONE_BENCHMARK_CORTEX",trait="SALO2024_LDH_META Track A")];hc[,`:=`(dataset="PMID37824647 author Adult",n_donors=2,scope="STRICT_CLONE_BENCHMARK_CORTEX",trait="SALO2024_LDH_META Track A")]
fwrite(c,file.path(od,"SALO_ADULT_CTS_FINAL.tsv"),sep="\t");fwrite(hc,file.path(od,"SALO_ADULT_JOINT_H2_FINAL.tsv"),sep="\t");fwrite(h,file.path(od,"SALO_ALL_104_ANNOTATIONS.tsv"),sep="\t")
log<-readLines(file.path(od,"SALO_Adult_joint.log"));ss<-log[grepl("Total Observed scale h2:|Lambda GC:|Mean Chi\\^2:|Intercept:|Ratio:",log)]
writeLines(c("# Salo LDH adult-cortex S-LDSC benchmark", "", "This is a cortical genetic-context benchmark reconstructed from author Adult snATAC labels (two donors aged 25 and 40), not spinal-cord localization or a disease-state expression analysis.","", "## Formal result",ss,"",paste("CTS positive-coefficient tests with FDR across all seven labels <0.05:",sum(c$FDR_CTS_7<.05)),paste("CTS tests with conservative cross-method global FDR across 14 tests <0.05:",sum(c$FDR_global_14<.05)),paste("Joint h2 custom-annotation enrichment tests with seven-test FDR<0.05:",sum(hc$FDR_h2_7<.05)),"", "All negative coefficients and non-significant results are retained. The CTS primary family and joint-annotation sensitivity family were locked before these new results. Global BH combines both families without selecting the more favorable method. Baseline-LD v2.2's 97 annotations are covariates, not additional selected cell types.","", "N is total cases+controls (829,699); no unverified population prevalence or liability-scale transform is used. Source INFO is not distributed. SNPs are strict HM3 with MAF>0.05, exact coordinates/alleles and conservative palindrome exclusion, and the hg19 chr6:25–34Mb MHC interval is excluded.","", "The two reference donors are reported explicitly. Cell counts are not independent biological replicates. This healthy cortex reference cannot establish LDH disease direction, disc-to-DRG communication, or patient-level cell differential effects."),file.path(od,"SLDSC_BENCHMARK_REPORT.md"))
writeLines(capture.output(sessionInfo()),file.path(od,"summary_sessionInfo.txt"));writeLines(format(Sys.time(),tz="UTC"),file.path(od,"sldsc.done"))
